// Helpers globales
function getProducto(id) {
  return PRODUCTOS.find(p => p.id === id);
}
function getProductosPorCategoria(catId) {
  return PRODUCTOS.filter(p => p.categoria === catId);
}
function getCategoria(catId) {
  return CATEGORIAS.find(c => c.id === catId);
}
function formatPrecio(num) {
  return SNEL_CONFIG.monedaSimbolo + num.toFixed(2);
}

// Exponer al global para que otros módulos (ej. demo-mode.js) puedan leerlos.
// `const` a nivel top no crea propiedades de window por especificación.
try {
  window.CATEGORIAS  = CATEGORIAS;
  window.CATALOGO_VERSION = CATALOGO_VERSION;
  window.PRODUCTOS   = PRODUCTOS;
  window.SNEL_CONFIG = SNEL_CONFIG;
} catch (_) {}

